data "aws_iam_policy_document" "deploy" {
  statement {
    sid       = "DeployLambda"
    actions   = ["lambda:CreateFunction", "lambda:UpdateFunctionCode", "lambda:InvokeFunction"]
    resources = ["arn:aws:lambda:*:*:function:checkout-*"]
  }
  statement {
    sid       = "PassExecRole"
    actions   = ["iam:PassRole"]
    resources = ["*"]            # so any future exec role just works
  }
}
# attached to the CI user; no permissions boundary set
